import { useEffect, useState } from 'react';
import io from 'socket.io-client';

// 部屋の型定義（部屋IDと参加人数）
type Room = { id: string; count: number };

// Socket.io クライアントを初期化（WebSocketで接続）
const socket = io('/', { path: '/socket.io', transports: ['websocket'] });

export default function Room() {
  // 状態管理：部屋一覧
  const [rooms, setRooms] = useState<Room[]>([]);

  // 選択中の部屋ID
  const [selectedRoom, setSelectedRoom] = useState<string | null>(null);

  // 選択中の部屋にいるプレイヤー一覧
  const [roomPlayers, setRoomPlayers] = useState<string[]>([]);

  // 入力されたプレイヤー名
  const [name, setName] = useState('');

  // 入室済みの部屋ID（入室済みかどうかを判定するため）
  const [joinedRoom, setJoinedRoom] = useState<string | null>(null);

  // 初回マウント時にSocket.ioのイベントを設定
useEffect(() => {
  socket.on('connect', () => {
    console.log('✅ Socket.io 接続成功:', socket.id);
  });

  socket.on('roomList', (list: Room[]) => {
    console.log('📦 受け取った部屋一覧:', list);
    setRooms(list);
  });

  socket.on('lobbyUpdate', (players: string[]) => {
    setRoomPlayers(players);
  });

  return () => {
    socket.disconnect();
  };
}, []);



  // 部屋をクリックしたときの処理
  const handleSelectRoom = (roomId: string) => {
    setSelectedRoom(roomId); // 選択状態を更新
    socket.emit('getRoomPlayers', roomId); // サーバーにプレイヤー一覧をリクエスト
  };

  // 入室ボタンを押したときの処理
  const handleJoin = () => {
    if (selectedRoom && name.trim()) {
      socket.emit('joinRoom', { roomId: selectedRoom, name }); // サーバーに入室リクエスト
      setJoinedRoom(selectedRoom); // 入室状態を更新
    }
  };

  return (
    <div style={styles.container}>
      {/* 左側：部屋一覧 */}
      <div style={styles.roomList}>
        <h2>🗂️ 部屋一覧</h2>
        {rooms.map((room) => (
          <div
            key={room.id}
            style={{
              ...styles.roomItem,
              backgroundColor: selectedRoom === room.id ? '#1f2a2f' : '#1e1e1e',
            }}
            onClick={() => handleSelectRoom(room.id)}
          >
            <strong>{room.id}</strong>
            <span>{room.count}人</span>
          </div>
        ))}
      </div>

      {/* 右側：部屋の詳細表示 */}
      <div style={styles.roomDetail}>
        {selectedRoom ? (
          <>
            <h2>🏠 {selectedRoom}</h2>
            <p>現在の参加者：</p>
            <ul>
              {roomPlayers.map((p, i) => (
                <li key={i}>{p}</li>
              ))}
            </ul>

            {/* 入室済みかどうかで表示を切り替え */}
            {joinedRoom === selectedRoom ? (
              <p style={{ color: '#00ffcc' }}>✅ 入室済み</p>
            ) : (
              <>
                <input
                  type="text"
                  placeholder="名前を入力"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  style={styles.input}
                />
                <button onClick={handleJoin} style={styles.joinButton}>
                  この部屋に入る
                </button>
              </>
            )}
          </>
        ) : (
          <p>部屋を選択してください</p>
        )}
      </div>
    </div>
  );
}

// 🎮 ゲーム風デザインのスタイル定義
const styles = {
  container: {
    display: 'flex',
    padding: '2rem',
    fontFamily: '"Press Start 2P", monospace', // ピクセル風フォント（Google Fontsで読み込み必要）
    gap: '2rem',
    backgroundColor: '#121212', // ダーク背景
    color: '#00ffcc', // ネオンカラー
    minHeight: '100vh',
  },
  roomList: {
    width: '40%',
    paddingRight: '1rem',
  },
  roomItem: {
    padding: '1rem',
    backgroundColor: '#1e1e1e',
    border: '2px solid #00ffcc',
    borderRadius: '8px',
    marginBottom: '0.75rem',
    cursor: 'pointer',
    boxShadow: '0 0 10px #00ffcc88',
    transition: 'transform 0.2s, box-shadow 0.2s',
    display: 'flex',
    justifyContent: 'space-between',
  },
  roomDetail: {
    width: '60%',
    backgroundColor: '#1a1a1a',
    padding: '1.5rem',
    borderRadius: '8px',
    boxShadow: '0 0 15px #00ffcc88',
    border: '2px solid #00ffcc',
  },
  joinButton: {
    marginTop: '1rem',
    padding: '0.75rem 1.5rem',
    backgroundColor: '#00ffcc',
    color: '#121212',
    border: 'none',
    borderRadius: '6px',
    cursor: 'pointer',
    fontWeight: 'bold',
    fontSize: '1rem',
    boxShadow: '0 0 10px #00ffcc',
    transition: 'background-color 0.2s, box-shadow 0.2s',
  },
  input: {
    padding: '0.5rem',
    width: '100%',
    marginTop: '1rem',
    marginBottom: '0.5rem',
    fontSize: '1rem',
    backgroundColor: '#2a2a2a',
    color: '#00ffcc',
    border: '1px solid #00ffcc',
    borderRadius: '4px',
  },
};
